-- 127 | 2026-11-21 | An Giang OLD wave 3/3. Public research, NOT checked-in or confirmed retail.
-- Pre-2025 province/district boundaries. No GPS, visits, customers or sales status fabricated.
WITH src AS (SELECT x.*,md5('fbmn:angiang-old:wave03:'||x.source_key) dg
 FROM jsonb_to_recordset('[{"district":"Huyện Châu Thành","name":"Nhà sách Châu Thành","address_line":"32 Tôn Thất Đạm, thị trấn An Châu cũ, huyện Châu Thành","category":"nha_sach","phone":"0939199900","tax_code":null,"source_key":"gmap:ChIJWXoGTccSCjERbjbO-kuqeCI","source_url":"https://www.google.com/maps/search/?api=1&query=Nh%C3%A0%20s%C3%A1ch%20Ch%C3%A2u%20Th%C3%A0nh%2032%20T%C3%B4n%20Th%E1%BA%A5t%20%C4%90%E1%BA%A1m%2C%20th%E1%BB%8B%20tr%E1%BA%A5n%20An%20Ch%C3%A2u%20c%C5%A9%2C%20huy%E1%BB%87n%20Ch%C3%A2u%20Th%C3%A0nh%20An%20Giang&query_place_id=ChIJWXoGTccSCjERbjbO-kuqeCI","verification_note":"Địa điểm bản đồ; chưa kiểm tra biển hiệu, nhóm hàng hoặc tình trạng bán lẻ năm 2026."},{"district":"Huyện Chợ Mới","name":"Hiệu sách Bích Ngọc","address_line":"14 Lê Lợi, thị trấn Chợ Mới cũ, huyện Chợ Mới","category":"nha_sach","phone":"02963883182","tax_code":null,"source_key":"gmap:ChIJa4EFdtYUCjERYwv_LtTUCwU","source_url":"https://www.google.com/maps/search/?api=1&query=Hi%E1%BB%87u%20s%C3%A1ch%20B%C3%ADch%20Ng%E1%BB%8Dc%2014%20L%C3%AA%20L%E1%BB%A3i%2C%20th%E1%BB%8B%20tr%E1%BA%A5n%20Ch%E1%BB%A3%20M%E1%BB%9Bi%20c%C5%A9%2C%20huy%E1%BB%87n%20Ch%E1%BB%A3%20M%E1%BB%9Bi%20An%20Giang&query_place_id=ChIJa4EFdtYUCjERYwv_LtTUCwU","verification_note":"Địa điểm bản đồ; chưa kiểm tra biển hiệu, nhóm hàng hoặc tình trạng bán lẻ năm 2026."},{"district":"Huyện Chợ Mới","name":"Văn phòng phẩm Bát Đạt","address_line":"60 Lê Lợi, thị trấn Chợ Mới cũ, huyện Chợ Mới","category":"van_phong_pham","phone":"02963883120","tax_code":null,"source_key":"angiangtoplist:batdat:60-leloi-chomoi","source_url":"https://angiangtoplist.com/top-7-shop-ban-dung-cu-ve-o-an-giang-day-du-gia-hat-de/","verification_note":"Nguồn danh bạ dụng cụ vẽ/học tập."},{"district":"Huyện Thoại Sơn","name":"Hiệu sách Thái Hưng","address_line":"459 Nguyễn Huệ, thị trấn Núi Sập cũ, huyện Thoại Sơn","category":"nha_sach","phone":"0942013120","tax_code":null,"source_key":"gmap:ChIJlZQh28sJCjERclpMp-vt7-s","source_url":"https://www.google.com/maps/search/?api=1&query=Hi%E1%BB%87u%20s%C3%A1ch%20Th%C3%A1i%20H%C6%B0ng%20459%20Nguy%E1%BB%85n%20Hu%E1%BB%87%2C%20th%E1%BB%8B%20tr%E1%BA%A5n%20N%C3%BAi%20S%E1%BA%ADp%20c%C5%A9%2C%20huy%E1%BB%87n%20Tho%E1%BA%A1i%20S%C6%A1n%20An%20Giang&query_place_id=ChIJlZQh28sJCjERclpMp-vt7-s","verification_note":"Địa điểm bản đồ; chưa kiểm tra biển hiệu, nhóm hàng hoặc tình trạng bán lẻ năm 2026."},{"district":"Huyện Thoại Sơn","name":"Hiệu sách Song Kim","address_line":"152 Thoại Ngọc Hầu, ấp Nam Sơn, huyện Thoại Sơn","category":"nha_sach","phone":"0945675218","tax_code":null,"source_key":"gmap:ChIJQd-JAe8JCjERq12DEKZFuMM","source_url":"https://www.google.com/maps/search/?api=1&query=Hi%E1%BB%87u%20s%C3%A1ch%20Song%20Kim%20152%20Tho%E1%BA%A1i%20Ng%E1%BB%8Dc%20H%E1%BA%A7u%2C%20%E1%BA%A5p%20Nam%20S%C6%A1n%2C%20huy%E1%BB%87n%20Tho%E1%BA%A1i%20S%C6%A1n%20An%20Giang&query_place_id=ChIJQd-JAe8JCjERq12DEKZFuMM","verification_note":"Địa điểm bản đồ; chưa kiểm tra biển hiệu, nhóm hàng hoặc tình trạng bán lẻ năm 2026."}]'::jsonb) AS x(
 district text,name text,address_line text,category text,phone text,tax_code text,
 source_key text,source_url text,verification_note text)),
 ins AS (
 INSERT INTO public.field_prospects(id,area_visit_id,owner_sub,name,address_line,province,district,category,
 phone,tax_code,note,status,source_kind,research_source_key,research_source_url,research_batch)
 SELECT (substr(s.dg,1,8)||'-'||substr(s.dg,9,4)||'-5'||substr(s.dg,14,3)||'-8'||substr(s.dg,18,3)||'-'||substr(s.dg,21,12))::uuid,
 NULL,'ef943de4-18f7-49ef-8340-eefb18855534',s.name,s.address_line,'An Giang',s.district,s.category,s.phone,s.tax_code,
 'Nguồn công khai 21/11/2026; CHƯA GHÉ; GPS chưa xác minh; hoạt động bán lẻ chưa xác minh. '||s.verification_note||' Nguồn: '||s.source_url,
 'new','manual',s.source_key,s.source_url,'2026-11-21-an-giang-old-wave-03'
 FROM src s WHERE s.district IN ('Huyện Châu Thành','Huyện Chợ Mới','Huyện Thoại Sơn')
 AND s.source_url LIKE 'https://%'
 AND NOT EXISTS(SELECT 1 FROM public.customers c WHERE c.province='An Giang' AND c.district=s.district
 AND (lower(trim(c.name))=lower(trim(s.name)) OR (c.phone IS NOT NULL AND s.phone IS NOT NULL AND c.phone=s.phone)))
 AND NOT EXISTS(SELECT 1 FROM public.field_prospects p WHERE p.province='An Giang' AND p.district=s.district
 AND (p.research_source_key=s.source_key OR (lower(trim(p.name))=lower(trim(s.name)) AND lower(trim(p.address_line))=lower(trim(s.address_line)))
 OR (p.phone IS NOT NULL AND s.phone IS NOT NULL AND p.phone=s.phone) OR (p.tax_code IS NOT NULL AND s.tax_code IS NOT NULL AND p.tax_code=s.tax_code)))
 ON CONFLICT(research_source_key) WHERE research_source_key IS NOT NULL DO NOTHING RETURNING district,category,phone)
 SELECT district,count(*)::int inserted,count(*) FILTER(WHERE category='nha_sach')::int bookstores,count(*) FILTER(WHERE phone IS NOT NULL)::int phones FROM ins GROUP BY district ORDER BY district;